/**
 * Verify links against the emitted Astro/GitHub Pages directory structure.
 * Content lint checks authored Markdown; this audits links generated by layouts,
 * tags, series, cards and base-prefixed assets after the actual build.
 * No runtime code and no third-party DOM parser required.
 */
import fs from 'node:fs';
import path from 'node:path';

const TAGS = /<(a|link|img|script|iframe|source|video|audio|track)\b(?:[^"'<>]|"[^"]*"|'[^']*')*>/gi;
const ATTRS = /(?:^|\s)(href|src|poster|srcset)\s*=\s*(["'])([\s\S]*?)\2/gi;
const IDS = /(?:^|\s)(?:id|name)\s*=\s*(["'])(.*?)\1/gi;
const DEFAULT_SKIP = new Set(['games/beanrush.html', 'games/pixelraid.html']);

function decodeHtml(value) {
  return value
    .replace(/&(?:amp|quot|apos|lt|gt);/gi, (entity) =>
      ({ '&amp;': '&', '&quot;': '"', '&apos;': "'", '&lt;': '<', '&gt;': '>' })[entity.toLowerCase()])
    .replace(/&#(x[0-9a-f]+|[0-9]+);/gi, (_, code) => {
      const point = code[0].toLowerCase() === 'x' ? parseInt(code.slice(1), 16) : Number(code);
      return point > 0 && point <= 0x10ffff ? String.fromCodePoint(point) : '';
    });
}

function visibleMarkup(html) {
  // Inline scripts can contain literal HTML strings that are NOT rendered links.
  return html.replace(/<!--[\s\S]*?-->/g, '')
    .replace(/(<script\b(?:[^"'>]|"[^"]*"|'[^']*')*>)[\s\S]*?<\/script\s*>/gi, '$1</script>')
    .replace(/<style\b(?:[^"'>]|"[^"]*"|'[^']*')*>[\s\S]*?<\/style\s*>/gi, '');
}

function allHtml(root, folder = root, found = []) {
  for (const entry of fs.readdirSync(folder, { withFileTypes: true })) {
    const file = path.join(folder, entry.name);
    if (entry.isDirectory()) allHtml(root, file, found);
    else if (entry.isFile() && entry.name.endsWith('.html')) found.push(file);
  }
  return found;
}

function localPageUrl(file, root, base, site) {
  const relative = path.relative(root, file).split(path.sep).join('/');
  const route = relative === 'index.html' ? '/' :
    relative.endsWith('/index.html') ? '/' + relative.slice(0, -10) : '/' + relative;
  return new URL(base + route, site);
}

function builtFile(root, pathname, base) {
  if (base && pathname !== base && !pathname.startsWith(base + '/')) return null;
  const suffix = pathname.slice(base.length).replace(/^\/+/, '');
  const candidates = [suffix];
  try {
    const decoded = decodeURIComponent(suffix);
    if (decoded !== suffix) candidates.unshift(decoded);
  } catch { /* malformed UTF-8 path will not exist */ }
  for (const name of candidates) {
    for (const rel of [name, name.replace(/\/?$/, '/') + 'index.html', name + '.html']) {
      const absolute = path.resolve(root, rel);
      if (!absolute.startsWith(root + path.sep)) continue;
      if (fs.existsSync(absolute) && fs.statSync(absolute).isFile()) return absolute;
    }
  }
  return null;
}

function identifiers(file, cache) {
  if (cache.has(file)) return cache.get(file);
  const ids = new Set();
  const markup = visibleMarkup(fs.readFileSync(file, 'utf8'));
  for (const tag of markup.matchAll(/<[\w:-]+\b(?:[^"'>]|"[^"]*"|'[^']*')*>/gi)) {
    for (const hit of tag[0].matchAll(IDS)) ids.add(decodeHtml(hit[2]));
  }
  cache.set(file, ids);
  return ids;
}

export function auditBuiltLinks({ dist, base = '/blog', site = 'https://cui-and-jing.github.io', skip = DEFAULT_SKIP }) {
  const root = path.resolve(dist);
  if (!fs.existsSync(root) || !fs.statSync(root).isDirectory()) {
    throw new Error('Build directory is missing: ' + root);
  }
  const prefix = base === '/' ? '' : '/' + String(base).replace(/^\/+|\/+$/g, '');
  const origin = new URL(site);
  const errors = [];
  const cache = new Map();
  const files = allHtml(root).filter((file) => !skip.has(path.relative(root, file).split(path.sep).join('/')));
  let references = 0;

  for (const file of files) {
    const page = localPageUrl(file, root, prefix, origin);
    const name = path.relative(root, file).split(path.sep).join('/');
    const markup = visibleMarkup(fs.readFileSync(file, 'utf8'));

    const verify = (element, attribute, raw) => {
      const value = decodeHtml(raw.trim());
      if (!value || value === '#' || value.startsWith('data:') || value.startsWith('blob:')) return;
      references += 1;
      let target;
      try { target = new URL(value, page); }
      catch {
        errors.push({ page: name, value, reason: 'invalid URL' });
        return;
      }
      if (target.protocol === 'javascript:') {
        errors.push({ page: name, value, reason: 'unsafe javascript URL' });
        return;
      }
      if (!['http:', 'https:'].includes(target.protocol) || target.origin !== origin.origin) return;
      const targetFile = builtFile(root, target.pathname, prefix);
      if (!targetFile) {
        const reason = prefix && target.pathname !== prefix && !target.pathname.startsWith(prefix + '/')
          ? 'same-origin link bypasses ' + prefix + '/ base'
          : 'missing emitted route/asset';
        errors.push({ page: name, value, reason });
        return;
      }
      if (element === 'a' && attribute === 'href' && target.hash && !target.hash.startsWith('#:~:text=')
          && targetFile.endsWith('.html') && !DEFAULT_SKIP.has(path.relative(root, targetFile).split(path.sep).join('/'))) {
        let id;
        try { id = decodeURIComponent(target.hash.slice(1)); }
        catch { id = target.hash.slice(1); }
        if (id && !identifiers(targetFile, cache).has(id)) {
          errors.push({ page: name, value, reason: 'missing target fragment #' + id });
        }
      }
    };

    for (const tag of markup.matchAll(TAGS)) {
      const element = tag[1].toLowerCase();
      for (const match of tag[0].matchAll(ATTRS)) {
        const attribute = match[1].toLowerCase();
        if (attribute === 'srcset') {
          // Image data URLs contain literal commas and are self-contained resources.
          if (match[3].trim().startsWith('data:')) continue;
          for (const part of match[3].split(',')) {
            const address = part.trim().split(/\s+/)[0];
            if (address) verify(element, attribute, address);
          }
        } else verify(element, attribute, match[3]);
      }
    }
  }
  return { pages: files.length, references, errors };
}
